import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"容量与缩容","description":"","frontmatter":{},"headers":[],"relativePath":"modules/storage/capacity.md","filePath":"modules/storage/capacity.md","lastUpdated":0}`),a={name:`modules/storage/capacity.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="容量与缩容" tabindex="-1">容量与缩容 <a class="header-anchor" href="#容量与缩容" aria-label="Permalink to “容量与缩容”">​</a></h1><p>本页说明 EmakiStorage 的容量领域模型：<code>config.yml</code> 的 <code>capacity</code> 段、四来源容量、三级 <code>stackLimit</code>，以及容量调小时的缩容与溢出处理。</p><h2 id="capacity" tabindex="-1">capacity <a class="header-anchor" href="#capacity" aria-label="Permalink to “capacity”">​</a></h2><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">capacity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  base_slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">45</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  max_slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  warn_entry_count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  default_stack_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>base_slots</code></td><td>int</td><td><code>45</code></td><td>默认开放槽位数（45 = 5 × 9，与 <code>gui.storage_rows</code> 默认值一致）。</td></tr><tr><td><code>max_slots</code></td><td>int</td><td><code>1000</code></td><td>槽位总量硬上限，<code>0</code> 表示无限。</td></tr><tr><td><code>warn_entry_count</code></td><td>int</td><td><code>5000</code></td><td>条目数超过此值时向控制台记 warning，<code>0</code> 表示不提醒。</td></tr><tr><td><code>default_stack_limit</code></td><td>long</td><td><code>100</code></td><td>配置级单槽堆叠上限。此层的 <code>0</code> 表示不限制。</td></tr></tbody></table><h3 id="四来源容量" tabindex="-1">四来源容量 <a class="header-anchor" href="#四来源容量" aria-label="Permalink to “四来源容量”">​</a></h3><p><code>effectiveSlots</code> 由四个独立持久化的来源相加后钳制：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>effective = clamp(base_slots + 权限档位 + grantedSlots + purchasedSlots, 0, max_slots)</span></span></code></pre></div><p><code>max_slots</code> 为 <code>0</code> 时跳过上限钳制。四个来源分开存储，所以调小 <code>base_slots</code> 不会吃掉玩家已授予或已购买的槽位。</p><table tabindex="0"><thead><tr><th>来源</th><th>来自</th><th>可否为负</th></tr></thead><tbody><tr><td><code>baseSlots</code></td><td><code>capacity.base_slots</code></td><td>否（负值按 0 处理）</td></tr><tr><td><code>permissionSlots</code></td><td><code>emakistorage.slots.&lt;n&gt;</code> 的最大档位</td><td>否</td></tr><tr><td><code>grantedSlots</code></td><td><code>/estorage slot grant</code>、API <code>grantSlotsAsync</code>、Action <code>storage_grant_slot</code></td><td>是</td></tr><tr><td><code>purchasedSlots</code></td><td>GUI 付费扩容、Action <code>storage_unlock_slot</code></td><td>否</td></tr></tbody></table><p>页数由槽位数推导，不可反向配置：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>totalPages     = max(1, ceil(effectiveSlots / 每页格数))</span></span>
<span class="line"><span>reachablePages = max(1, ceil(usedSlots / 每页格数))</span></span></code></pre></div><p>第 1 页始终可达（空仓库也要能打开并接收第一件物品）；完全没有条目的页无法翻入。</p><p>将 <code>max_slots</code> 设为 <code>0</code>（无限）前请确认内存充足。配置注释给出的量级是单玩家 10 万条目约占 100–200MB 堆内存，这是推算值，未实测。</p><h2 id="三级-stacklimit" tabindex="-1">三级 stackLimit <a class="header-anchor" href="#三级-stacklimit" aria-label="Permalink to “三级 stackLimit”">​</a></h2><p>单槽上限按「最具体优先」解析，三层：</p><table tabindex="0"><thead><tr><th>层级</th><th>存储位置</th><th>设置方式</th><th><code>0</code> 的含义</th></tr></thead><tbody><tr><td>条目级</td><td><code>meta.yml</code> 对应条目</td><td><code>/estorage stacklimit slot</code>、API <code>setSlotStackLimitAsync</code>、Action <code>storage_set_stacklimit</code> 带 <code>slot</code></td><td>继承玩家级</td></tr><tr><td>玩家级</td><td><code>meta.yml</code> 的 <code>defaultStackLimit</code></td><td><code>/estorage stacklimit player</code>、API <code>setStackLimitAsync</code>、Action <code>storage_set_stacklimit</code> 不带 <code>slot</code></td><td>继承配置级</td></tr><tr><td>配置级</td><td><code>config.yml</code> 的 <code>capacity.default_stack_limit</code></td><td>配置文件</td><td><strong>不限制</strong>（等价 <code>Long.MAX_VALUE</code>）</td></tr></tbody></table><p>同一个 <code>0</code> 在不同层级语义不同：条目级与玩家级的 <code>0</code> 表示「继承上一级」，配置级的 <code>0</code> 表示「无限制」。解析顺序是条目级 <code>&gt; 0</code> → 玩家级 <code>&gt; 0</code> → 配置级，配置级 <code>&lt;= 0</code> 时返回 <code>Long.MAX_VALUE</code>。</p><p>另有 <code>emakistorage.stacklimit.&lt;n&gt;</code> 权限档位可提供玩家级上限，同样取最大值、不支持通配。</p><h2 id="同物品跨槽位存储" tabindex="-1">同物品跨槽位存储 <a class="header-anchor" href="#同物品跨槽位存储" aria-label="Permalink to “同物品跨槽位存储”">​</a></h2><p>默认情况下单槽存满即拒绝剩余部分。<code>behavior.multi_slot_stacking</code> 设为 <code>true</code> 后，同一物品可自动占用新槽位继续存储。</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">behavior</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  multi_slot_stacking</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"> # true = 允许一个条目跨多格</span></span></code></pre></div><p>单槽上限 100、手上 120 个橡木原木：</p><table tabindex="0"><thead><tr><th>开关</th><th>结果</th></tr></thead><tbody><tr><td><code>false</code>（默认）</td><td>存入 100，剩余 20 被拒绝（<code>slot_full</code>）</td></tr><tr><td><code>true</code></td><td>存入 120，显示为 <code>[100]</code> <code>[20]</code> 两格</td></tr></tbody></table><h3 id="占用格数如何推导" tabindex="-1">占用格数如何推导 <a class="header-anchor" href="#占用格数如何推导" aria-label="Permalink to “占用格数如何推导”">​</a></h3><p>占用格数不持久化，每次读取时由数量推导：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>span      = ceil(条目数量 / 单槽上限)</span></span>
<span class="line"><span>usedSlots = 所有条目 span 之和</span></span></code></pre></div><p><code>usedSlots</code> 必须计入 span，否则玩家能用 45 个跨格条目占满 90 格却只被记 45 格，直接突破 <code>max_slots</code>。</p><p>单槽上限为无限（<code>default_stack_limit: 0</code> 且未被玩家级/条目级覆盖）时 <code>span</code> 恒为 <code>1</code>：无限的百分比没有意义，也就没有可溢出到第二格的部分。</p><h3 id="取出与合并" tabindex="-1">取出与合并 <a class="header-anchor" href="#取出与合并" aria-label="Permalink to “取出与合并”">​</a></h3><p>跨格条目的多个格子<strong>共享同一个数量池</strong>，点任意一格取出都从条目总量扣除。因为 span 是推导值，收缩是自动的，不存在「合并」这一步：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>120 个（上限 100）  →  [100] [20]      占用 2 格</span></span>
<span class="line"><span>点第 1 格取出 20    →  [100]           占用 1 格，后面的条目前滚填补</span></span></code></pre></div><p>条目本身存储在无空洞的紧凑列表中，因此「后面的物品前滚填充」是列表的自然状态，界面每次刷新都会重新推导。</p><h3 id="界面显示" tabindex="-1">界面显示 <a class="header-anchor" href="#界面显示" aria-label="Permalink to “界面显示”">​</a></h3><p>每格显示<strong>本格的量</strong>而不是条目总量（第 1 格 <code>100/100</code>，第 2 格 <code>20/100</code>），与玩家阅读原版容器的方式一致。跨格时额外追加一行 <code>gui.entry.span_total</code>，说明条目总量与占用格数。</p><h3 id="与其他机制的关系" tabindex="-1">与其他机制的关系 <a class="header-anchor" href="#与其他机制的关系" aria-label="Permalink to “与其他机制的关系”">​</a></h3><table tabindex="0"><thead><tr><th>面</th><th>行为</th></tr></thead><tbody><tr><td>总槽位限制</td><td>仍然生效。装不下的部分照旧被拒绝，不会突破 <code>capacity.max_slots</code>。</td></tr><tr><td><code>%used_slots%</code>（占位符、<code>/estorage info</code>、界面容量行）</td><td>自动跟随新语义：开关开启后显示的是<strong>占用格数</strong>而不是条目数。</td></tr><tr><td><code>/estorage stacklimit slot &lt;n&gt;</code>、API <code>setSlotStackLimitAsync</code>、<code>StorageEntrySnapshot.slotIndex</code></td><td>仍是<strong>条目下标</strong>，不是界面显示格号。上限属于条目本身，条目下标才是稳定身份。开关关闭时两者相同。</td></tr><tr><td>搜索命中数 <code>%visible%</code></td><td>仍是命中的<strong>条目数</strong>，因为玩家搜的是物品而不是格子。</td></tr><tr><td>溢出锁定</td><td>按 span 累加边界。跨越容量边界的条目整条锁定（只读可取出），保持零丢失。</td></tr><tr><td>持久化</td><td>格式不变。跨格只是条目数量变大，数量本来就是变长整数。</td></tr></tbody></table><h3 id="关掉开关后" tabindex="-1">关掉开关后 <a class="header-anchor" href="#关掉开关后" aria-label="Permalink to “关掉开关后”">​</a></h3><p>从 <code>true</code> 改回 <code>false</code> 不丢数据：已超过单槽上限的条目仍占一格、显示按 100% 截断、拒绝新存入、可正常取空。</p><h3 id="开销" tabindex="-1">开销 <a class="header-anchor" href="#开销" aria-label="Permalink to “开销”">​</a></h3><p>开关关闭时 <code>usedSlots</code> 为 O(1)（直接取条目数）。开启后需遍历全部条目累加 span，单玩家条目数很大时每次界面刷新的开销会上升。容量在每次刷新时只解析一次而非每格一次，但遍历本身无法避免。</p><h2 id="缩容与溢出" tabindex="-1">缩容与溢出 <a class="header-anchor" href="#缩容与溢出" aria-label="Permalink to “缩容与溢出”">​</a></h2><p>容量调小导致占用超出边界时，按 <code>unlock.overflow_policy</code> 处理。该键本身在<a href="./configuration.html">配置详解</a>的 <code>unlock</code> 段。</p><h3 id="四种-overflow-policy" tabindex="-1">四种 overflow_policy <a class="header-anchor" href="#四种-overflow-policy" aria-label="Permalink to “四种 overflow_policy”">​</a></h3><table tabindex="0"><thead><tr><th>取值</th><th>行为</th></tr></thead><tbody><tr><td><code>lock_readonly</code></td><td>超出容量边界的条目只读：可取出、不可存入，取空后自动释放。推荐。</td></tr><tr><td><code>compact</code></td><td>超出条目前滚填补空位。条目本身已存储在无空洞的紧凑列表中，因此「前滚」就是列表的自然状态；仍然装不下的部分退化为 <code>lock_readonly</code>。</td></tr><tr><td><code>return_inventory</code></td><td>尝试把超出条目退回玩家背包，装不下的退化为 <code>lock_readonly</code>。玩家离线时不退还，直接锁定。</td></tr><tr><td><code>reject_change</code></td><td>直接拒绝本次缩容。</td></tr></tbody></table><p>四种策略全部零丢失，<strong>不提供</strong> <code>drop</code> 与 <code>delete</code>：不可逆数据丢失不应由调整配置隐式触发。</p><p>溢出状态不持久化。它由容量与占用推导，在登录、重载、权限变化、命令授予等容量变化时机重新计算，因此不会出现存储标记与事实不同步的情况。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to “相关页面”">​</a></h2><ul><li><a href="./configuration.html">配置详解</a>：<code>unlock</code>、<code>behavior</code>、<code>persistence</code> 等其余 <code>config.yml</code> 段落。</li><li><a href="./gui.html">界面与展示</a>：每页格数如何由 <code>gui.storage_rows</code> 决定。</li><li><a href="./unlock-costs.html">付费扩容档位</a>：<code>purchasedSlots</code> 的计价与购买流程。</li><li><a href="./commands.html">命令与权限</a>：<code>/estorage slot</code>、<code>/estorage stacklimit</code> 与权限档位。</li><li><a href="./api.html">API 与集成</a>：<code>StorageCapacity</code> 各字段与配置项的对应关系。</li></ul>`,49)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};